def parse_user_agent(ua_string):
    if not ua_string:
        return "Dispositivo Web"
    ua = ua_string.lower()
    if "android" in ua:
        return "Android Mobile" if "mobile" in ua else "Android TV / Box"
    elif "iphone" in ua:
        return "Apple iPhone"
    elif "ipad" in ua:
        return "Apple iPad"
    elif "smart-tv" in ua or "tizen" in ua or "webos" in ua:
        return "Smart TV"
    elif "windows" in ua:
        return "Windows PC"
    elif "linux" in ua:
        return "Linux PC"
    return "PC / Desktop"

def parse_trial_api_response(raw_text, cfg):
    """Extrai os dados reais da API Infinity/PanelBR sem valores fictícios de modelo."""
    now_ts = int(time.time())
    hours = float(cfg.get("trial_duration_hours") or 6)
    fallback_exp_ts = now_ts + int(hours * 3600)
    fallback_exp_str = datetime.fromtimestamp(fallback_exp_ts).strftime("%d/%m/%Y às %H:%M")
    fallback_dns = (cfg.get("dns_list", "").splitlines()[0] if cfg.get("dns_list") else "").strip().rstrip("/")

    res = {
        "username": "",
        "password": "",
        "dns": fallback_dns,
        "m3u_url": "",
        "plan_type": "Teste Completo",
        "max_connections": "1",
        "created_formatted": datetime.now().strftime("%d/%m/%Y %H:%M:%S"),
        "expires_at": fallback_exp_ts,
        "expires_formatted": fallback_exp_str,
        "payment_link": "",
        "apps_smart_tv": "",
        "apps_android": "",
        "raw_message": raw_text.strip() if raw_text else ""
    }

    if not raw_text or not raw_text.strip():
        return res

    cleaned = raw_text.strip()

    try:
        data = json.loads(cleaned)
        if isinstance(data, dict):
            if isinstance(data.get("data"), dict):
                data = {**data, **data["data"]}
            u = data.get("username") or data.get("user") or data.get("login")
            p = data.get("password") or data.get("pass") or data.get("senha")
            dns = data.get("dns") or data.get("server") or data.get("host")
            plan = data.get("package") or data.get("plan_type") or data.get("plan")
            pay = data.get("payUrl") or data.get("payment_link") or data.get("pay_url")
            exp_formatted = data.get("expiresAtFormatted") or data.get("expiresAt") or data.get("expires_at")
            reply = data.get("reply") or data.get("message") or data.get("text") or ""
            created = data.get("createdAtFormatted") or data.get("createdAt")
            conns = data.get("connections") or data.get("max_connections")
            if created: res["created_formatted"] = str(created)
            if conns: res["max_connections"] = str(conns)

            if u: res["username"] = str(u).strip()
            if p: res["password"] = str(p).strip()
            if dns: res["dns"] = str(dns).strip().rstrip("/")
            if plan: res["plan_type"] = str(plan).replace("🔹", "").replace("TESTE", "Teste").strip()
            if pay: res["payment_link"] = str(pay).strip()
            if exp_formatted: res["expires_formatted"] = str(exp_formatted).strip()
            if reply: res["raw_message"] = str(reply).strip()

            if reply and isinstance(reply, str):
                tv_matches = []
                for p_match in re.findall(r'(\*?Parce?ria[^\n*]+\*?[\s\S]*?\*COD:\*?\s*[^\n]+)', reply, re.IGNORECASE):
                    clean_p = p_match.replace("*", "").replace("—", "").strip()
                    if clean_p: tv_matches.append(clean_p)
                if tv_matches:
                    res["apps_smart_tv"] = "\n\n".join(tv_matches)

                and_matches = []
                for a_match in re.findall(r'(\*?App:\s*[^\n*]+[\s\S]*?(?=——|—|\n\n\ud83d|\n\n\u26a0|$))', reply, re.IGNORECASE):
                    clean_a = a_match.replace("*", "").replace("—", "").strip()
                    if clean_a: and_matches.append(clean_a)
                if and_matches:
                    res["apps_android"] = "\n\n".join(and_matches)

                m3u_find = re.search(r'(https?://[^\s\"\'<>]+(?:get\.php|\.m3u8?)[^\s\"\'<>]*)', reply, re.I)
                if m3u_find:
                    res["m3u_url"] = m3u_find.group(1).strip()

                dns_find = re.search(r'(?:dns|servidor|url|host)\s*[:=\-*]+\s*(https?://[^\s\"\'<>*]+)', reply, re.I)
                if dns_find and not dns:
                    res["dns"] = dns_find.group(1).strip().rstrip("/")
    except Exception:
        pass

    def find_payment_link(value, depth=0):
        if depth > 5:
            return ""
        if isinstance(value, dict):
            for key, item in value.items():
                if re.search(r"pay(?:ment|url|link)?|checkout|renov|assinar|fatura|pagamento|invoice", str(key), re.I):
                    if isinstance(item, str) and re.match(r"^https?://", item.strip(), re.I):
                        return item.strip().rstrip('.,;')
            for item in value.values():
                found = find_payment_link(item, depth + 1)
                if found:
                    return found
        elif isinstance(value, list):
            for item in value:
                found = find_payment_link(item, depth + 1)
                if found:
                    return found
        return ""

    if not res["payment_link"]:
        try:
            res["payment_link"] = find_payment_link(json.loads(cleaned))
        except (ValueError, TypeError):
            pass
    if not res["payment_link"]:
        payment_match = re.search(
            r"(?:assinar\s*[/\-]\s*renovar|renovar|assin(?:ar|atura)|pagamento|checkout|fatura|link\s*(?:de\s*)?pagamento)"
            r"[^\n]{0,90}?(https?://[^\s<>\\\"']+)", cleaned, re.I)
        if payment_match:
            res["payment_link"] = payment_match.group(1).rstrip('.,;)*')

    if not res["username"]:
        u_m = re.search(r"(?:usu[aá]rio|user|login)\s*[:=\-*]+\s*([A-Za-z0-9_.\-]+)", cleaned, re.I)
        if u_m: res["username"] = u_m.group(1).strip()

    if not res["password"]:
        p_m = re.search(r"(?:senha|password|pass)\s*[:=\-*]+\s*([A-Za-z0-9_.\-]+)", cleaned, re.I)
        if p_m: res["password"] = p_m.group(1).strip()

    if not res["payment_link"]:
        pay_m = re.search(r"(https?://[^\s\"'<>]+(?:checkout|fatura|pagamento|mercadopago|pix|assinar|pay)[^\s\"'<>]*)", cleaned, re.I)
        if pay_m: res["payment_link"] = pay_m.group(1).strip()

    if res["m3u_url"]:
        try:
            sp = urllib.parse.urlsplit(res["m3u_url"])
            if sp.scheme and sp.netloc:
                res["dns"] = f"{sp.scheme}://{sp.netloc}"
            qs = urllib.parse.parse_qs(sp.query)
            if not res["username"] and qs.get("username"):
                res["username"] = qs["username"][0].strip()
            if not res["password"] and qs.get("password"):
                res["password"] = qs["password"][0].strip()
        except Exception:
            pass

    if res["dns"] and not res["dns"].startswith(("http://", "https://")):
        res["dns"] = "http://" + res["dns"]

    if not res["m3u_url"] and res["username"] and res["password"] and res["dns"]:
        res["m3u_url"] = f"{res['dns']}/get.php?username={urllib.parse.quote(res['username'])}&password={urllib.parse.quote(res['password'])}&type=m3u_plus&output=ts"

    return res

