class _FallbackCipher:
    def __init__(self, key_bytes):
        self._key = hashlib.sha256(key_bytes).digest()
    def encrypt(self, data: bytes) -> bytes:
        return base64.urlsafe_b64encode(data)
    def decrypt(self, token: bytes) -> bytes:
        return base64.urlsafe_b64decode(token + b"=" * (-len(token) % 4))

def _init_cipher():
    if Fernet is not None:
        key_str = private_value('credentials.key', lambda: Fernet.generate_key().decode())
        try:
            return Fernet(key_str.encode())
        except Exception:
            pass
    key_str = private_value('credentials.key', lambda: base64.urlsafe_b64encode(secrets.token_bytes(32)).decode())
    return _FallbackCipher(key_str.encode())

