def digest(value): return hashlib.sha256(str(value).encode()).hexdigest()
def seal(value): return CIPHER.encrypt(json.dumps(value,ensure_ascii=False).encode()).decode()
def unseal(value):
    if not value:
        return {}
    try:
        return json.loads(CIPHER.decrypt(str(value).encode()))
    except Exception:
        try:
            parsed = json.loads(str(value))
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            if str(value).startswith(("http://", "https://")):
                return {"url": str(value).strip()}
            return {}

@contextmanager
def database():
    conn=sqlite3.connect(DB_PATH,timeout=15)
    conn.row_factory=sqlite3.Row
    conn.execute('PRAGMA foreign_keys=ON')
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally: conn.close()

def row(sql,args=()):
    with database() as db:
        result=db.execute(sql,args).fetchone()
        return dict(result) if result else None
def rows(sql,args=()):
    with database() as db:return [dict(r) for r in db.execute(sql,args).fetchall()]
def execute(sql,args=()):
    with database() as db:return db.execute(sql,args).rowcount
def setting(key,default=''):
    r=row('SELECT value FROM site_settings WHERE key=?',(key,))
    return r['value'] if r else default
def save_setting(key,value):
    execute('INSERT INTO site_settings(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(key,str(value)))

def _read_legacy_streamflix_settings():
    """Importa configurações do streamflix.db caso exista na mesma pasta da VPS."""
    sf_db = BASE_DIR / 'streamflix.db'
    if not sf_db.exists():
        return {}
    try:
        conn = sqlite3.connect(sf_db, timeout=5)
        conn.row_factory = sqlite3.Row
        items = conn.execute("SELECT key, value FROM settings").fetchall()
        conn.close()
        return {r["key"]: r["value"] for r in items if r["value"]}
    except Exception:
        return {}

def safe_url(value):
    try:
        raw = str(value or '').strip()
        if not raw:
            return None
        if not raw.startswith(('http://', 'https://')) and '.' in raw and not raw.startswith('/'):
            raw = 'http://' + raw
        u=urllib.parse.urlsplit(raw)
        if u.scheme not in ('http','https') or not u.hostname:
            return None
        host=u.hostname
        if host in ('localhost',) or host.endswith(('.local','.internal','.localhost')):
            return None
        try:
            ip = ipaddress.ip_address(host)
            if ip.is_loopback or ip.is_link_local or ip.is_unspecified:
                return None
        except ValueError:
            if '.' not in host:
                return None
        return urllib.parse.urlunsplit(u)
    except ValueError:
        return None

def server_origin(value):
    if not value:
        return None
    raw = re.sub(r'/(?:player_api|get)\.php.*$', '', str(value).strip(), flags=re.I).rstrip('/')
    valid=safe_url(raw)
    if not valid:
        return None
    u=urllib.parse.urlsplit(valid)
    return urllib.parse.urlunsplit((u.scheme,u.netloc,'','',''))

def candidate_servers(primary=None):
    """Lista ordenada de servidores DNS candidatos (primário, configurados, legados e oficiais)."""
    out = []
    def add(val):
        if not val:
            return
        for part in re.split(r'[\r\n,;\s]+', str(val)):
            orig = server_origin(part)
            if orig and orig not in out:
                out.append(orig)
    add(primary)
    add(setting('provider_dns'))
    legacy = _read_legacy_streamflix_settings()
    add(legacy.get('dns_list'))
    add(os.environ.get('IPTV_SERVER_URL'))
    add('http://zavryqonix.online:80')
    add('http://turkicdn.online:80')
    return out

def resolve_trial_api_url():
    val = setting('trial_api_url')
    if val:
        unsealed = unseal(val).get('url')
        if unsealed and safe_url(unsealed):
            return unsealed.strip()
        if safe_url(val):
            return str(val).strip()
    env_url = os.environ.get('IPTV_TRIAL_API_URL') or os.environ.get('STREAMFLIX_TRIAL_API_URL')
    if env_url and safe_url(env_url):
        return env_url.strip()
    legacy = _read_legacy_streamflix_settings()
    leg_url = legacy.get('trial_api_url')
    if leg_url and safe_url(leg_url):
        return leg_url.strip()
    return ''

def init_storage():
    with database() as db:
        db.execute('PRAGMA journal_mode=WAL')
        if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='accounts'").fetchone():
            db.executescript(SCHEMA)
    if not setting('admin_hash'):
        password=os.environ.get('NEXO_ADMIN_PASSWORD') or private_value('admin-inicial.txt',lambda:secrets.token_urlsafe(18))
        save_setting('admin_user','admin')
        save_setting('admin_hash',generate_password_hash(password))
        save_setting('admin_version',1)
    legacy = _read_legacy_streamflix_settings()
    default_dns = os.environ.get('IPTV_SERVER_URL') or legacy.get('dns_list') or 'http://zavryqonix.online:80\nhttp://turkicdn.online:80'
    for k,v in {'provider_dns':default_dns,'support_whatsapp':'5516995293243'}.items():
        if not setting(k):
            save_setting(k,v)
    trial_env = os.environ.get('IPTV_TRIAL_API_URL') or os.environ.get('STREAMFLIX_TRIAL_API_URL') or legacy.get('trial_api_url')
    if trial_env and not setting('trial_api_url'):
        save_setting('trial_api_url',seal({'url':trial_env}))

def playlist_url(c):
    srv = (c.get('server') or candidate_servers()[0]).rstrip('/')
    return srv+'/get.php?'+urllib.parse.urlencode({'username':c['username'],'password':c['password'],'type':'m3u_plus','output':'mpegts'})

def _read_http_decoded(response, max_bytes=48000000):
    raw = response.read(max_bytes)
    enc = (response.headers.get('Content-Encoding') or '').lower()
    if enc == 'gzip' or raw[:2] == b'\x1f\x8b':
        try:
            raw = gzip.decompress(raw)
        except Exception:
            pass
    return raw.decode('utf-8-sig', 'replace')

def provider_json(c, action=None, params=None, timeout=6):
    fields={'username':c['username'],'password':c['password']}
    if action:fields['action']=action
    fields.update(params or {})
    servers = candidate_servers(c.get('server'))
    user_agents = (
        'IPTVSmartersPro/3.1.5 (Linux; Android 12)',
        'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',
        'VLC/3.0.20 LibVLC/3.0.20'
    )
    last_err = None
    for srv in servers:
        url=srv.rstrip('/')+'/player_api.php?'+urllib.parse.urlencode(fields)
        for ua in user_agents[:2]:
            try:
                req=urllib.request.Request(url,headers={'User-Agent':ua,'Accept':'*/*'})
                with urllib.request.urlopen(req,timeout=timeout,context=SSL_CTX) as response:
                    txt = _read_http_decoded(response).strip()
                if not txt:
                    continue
                idx_obj, idx_arr = txt.find('{'), txt.find('[')
                idx = min(idx_obj, idx_arr) if (idx_obj >= 0 and idx_arr >= 0) else max(idx_obj, idx_arr)
                if idx > 0:
                    txt = txt[idx:]
                data = json.loads(txt)
                if not action and isinstance(data, dict) and isinstance(data.get('user_info'), dict):
                    if str(data['user_info'].get('auth')) == '0':
                        last_err = ValueError('Credenciais recusadas')
                        break
                c['server'] = srv
                return data
            except urllib.error.HTTPError as he:
                last_err = he
                if he.code in (401, 403, 404):
                    continue
            except Exception as e:
                last_err = e
                continue
    if last_err:
        raise last_err
    raise urllib.error.URLError('Servidor IPTV indisponível')

def fetch_m3u_text(c, timeout=14):
    servers = candidate_servers(c.get('server'))
    user_agents = (
        'IPTVSmartersPro/3.1.5 (Linux; Android 12)',
        'VLC/3.0.20 LibVLC/3.0.20',
        'Mozilla/5.0'
    )
    for srv in servers:
        url = srv.rstrip('/')+'/get.php?'+urllib.parse.urlencode({'username':c['username'],'password':c['password'],'type':'m3u_plus','output':'mpegts'})
        for ua in user_agents[:2]:
            try:
                req=urllib.request.Request(url,headers={'User-Agent':ua,'Accept':'*/*'})
                with urllib.request.urlopen(req,timeout=timeout,context=SSL_CTX) as response:
                    text=_read_http_decoded(response, 32000000)
                if text.lstrip('\ufeff \r\n').startswith('#EXTM3U') and '#EXTINF' in text:
                    c['server'] = srv
                    return text, srv
            except Exception:
                continue
    return None, None

def verify_m3u(c):
    text, _ = fetch_m3u_text(c, timeout=8)
    return bool(text)

def iso(value):return datetime.fromtimestamp(value/1000,timezone.utc).isoformat() if value else None
def timestamp(value):
    if value is None or value=='':return None
    try:
        if str(value).isdigit():
            n=int(value);return n if n>10**12 else n*1000
        text=str(value).strip().replace(' às ',' ').replace('Z','+00:00')
        if re.match(r'^\d{2}/\d{2}/\d{4}',text):
            date=datetime.strptime(text[:19],'%d/%m/%Y %H:%M:%S') if len(text)>=19 else datetime.strptime(text[:16],'%d/%m/%Y %H:%M')
        else:date=datetime.fromisoformat(text)
        if date.tzinfo is None:date=date.replace(tzinfo=timezone(timedelta(hours=-3)))
        return int(date.timestamp()*1000)
    except (ValueError,TypeError,OverflowError):return None

def allowed(a):return bool(a and not a['revoked'] and (a['provider_status']=='Active' or a['provider_status']=='External' and not a['is_trial']) and (not a['expires_at'] or a['expires_at']>now()) and (not a['is_trial'] or a['trial_deadline'] and a['trial_deadline']>now()))
def public_account(a):
    if not a:return None
    return {'id':a['id'],'username':a['username'],'plan':a['plan'],'expiresAt':iso(a['expires_at']),'trialDeadline':iso(a['trial_deadline']),
            'isTrial':bool(a['is_trial']),'locked':not allowed(a),'status':a['provider_status'],'paymentUrl':a['payment_url'],'connections':a['access_count']}

class ApiError(Exception):
    def __init__(self,message,status=400,code='REQUEST_ERROR',account=None):
        self.message=message;self.status=status;self.code=code;self.account=account

@app.errorhandler(ApiError)
def api_error(e):
    data={'error':e.message,'code':e.code,'serverNow':now()}
    if e.account:data['account']=public_account(e.account)
    return jsonify(data),e.status

@app.errorhandler(413)
def too_large(e):return jsonify(error='Solicitação muito grande.'),413

def current_account(required=True,active=False):
    token=session.get('user_token')
    a=row('SELECT a.*,s.id AS session_id FROM sessions s JOIN accounts a ON a.id=s.account_id WHERE s.id=? AND s.expires_at>? AND a.revoked=0',(digest(token),now())) if token else None
    if not a and required:raise ApiError('Entre para continuar.',401,'LOGIN_REQUIRED')
    if active and a and not allowed(a):raise ApiError('Seu acesso expirou. Renove para continuar.',403,'ACCESS_EXPIRED',a)
    return a

def login_response(a,trial=None):
    token=secrets.token_urlsafe(32)
    execute('INSERT INTO sessions(id,account_id,created_at,expires_at) VALUES(?,?,?,?)',(digest(token),a['id'],now(),now()+30*86400000))
    session['user_token']=token;session.permanent=True
    result={'account':public_account(a),'serverNow':now()}
    if trial:result['trial']=trial
    return jsonify(result)

def client_info(body=None):
    device=(body or {}).get('device') or {}
    if not isinstance(device,dict):device={}
    return {'ip':request.remote_addr or '', 'ua':request.headers.get('User-Agent','')[:1000],
            'model':str(device.get('model') or parse_user_agent(request.headers.get('User-Agent','')))[:150],
            'platform':str(device.get('platform') or '')[:100],'browser':str(device.get('browser') or '')[:150]}

def save_account(c,info=None,trial=None,body=None):
    old=row('SELECT * FROM accounts WHERE username=?',(c['username'],));info=info or {};u=info.get('user_info') or {};ci=client_info(body)
    if old and old['revoked']:raise ApiError('Acesso removido pelo administrador.',403)
    is_trial=bool(trial) or str(u.get('is_trial'))=='1' or bool(old and old['is_trial'] and not u)
    deadline=old['trial_deadline'] if old else None
    expiry=timestamp(u.get('exp_date')) if u else old['expires_at'] if old else None
    if trial:deadline=deadline or trial['expiry'];expiry=deadline
    if is_trial and not deadline:deadline=expiry
    incoming_expiry=timestamp(u.get('exp_date')) if u else None
    if old and old['is_trial'] and u and str(u.get('auth'))=='1' and str(u.get('is_trial'))=='0' and str(u.get('status')).lower()=='active' and (not incoming_expiry or incoming_expiry>(old['trial_deadline'] or 0)):
        is_trial=False;expiry=incoming_expiry
    elif is_trial and deadline:expiry=min(expiry or deadline,deadline)
    if body is None and old:ci.update(ip=old['last_ip'],model=old['device_model'],platform=old['platform'],browser=old['browser'])
    c_to_seal = dict(c)
    c_to_seal['servers'] = candidate_servers(c.get('server'))
    c_to_seal['server'] = c_to_seal['servers'][0]
    a={'id':old['id'] if old else uid(),'username':c['username'],'credentials':seal(c_to_seal),'payment_url':trial.get('paymentUrl') if trial else old['payment_url'] if old else None,
       'plan':trial.get('plan') if trial else old['plan'] if old else 'IPTV','created_at':old['created_at'] if old else now(), 'expires_at':expiry,
       'trial_deadline':deadline,'is_trial':int(is_trial),'provider_status':'Active' if not u or str(u.get('status','Active')).lower() in ('active','trial','') else str(u.get('status')),
       'last_verified':now() if u else old['last_verified'] if old else 0,'last_ip':ci['ip'],'device_model':ci['model'],'platform':ci['platform'],'browser':ci['browser'],
       'trial_details':seal({'apps':trial.get('apps',[])}) if trial else old['trial_details'] if old else None,'access_count':int(trial.get('connections') or 1) if trial else int(u.get('max_connections') or (old['access_count'] if old else 1) or 1)}
    keys=list(a);updates=','.join(k+'=excluded.'+k for k in keys if k not in ('id','created_at'))
    execute('INSERT INTO accounts('+','.join(keys)+') VALUES('+','.join('?' for _ in keys)+') ON CONFLICT(username) DO UPDATE SET '+updates,tuple(a.values()))
    return row('SELECT * FROM accounts WHERE id=?',(a['id'],))

def apps_from_reply(reply):
    result=[];counts={'smart':0,'android':0}
    for block in re.split(r'[—─_-]{4,}',str(reply or '')):
        clean=[re.sub(r'^[^\w]+','',line.replace('*','')).strip() for line in block.splitlines()]
        name=next((re.sub(r'^(?:app\s*:|parce?ria\s+)','',x,flags=re.I).strip() for x in clean if re.match(r'^(?:app\s*:|parce?ria\s+)',x,re.I)),None)
        if not name or re.search(r'loja|play\s*store|ntdow|downloader\s*store',name,re.I):continue
        downloader=next((re.sub(r'^[^:]+:\s*','',x) for x in clean if re.match(r'(?:c[oó]d(?:igo)?\s*)?downloader\s*:',x,re.I)),None)
        code=downloader or next((re.sub(r'^[^:]+:\s*','',x) for x in clean if re.match(r'c[oó]d(?:igo)?\s*:',x,re.I)),None)
        platform='android' if downloader or re.search(r'android|apk|xciptv|smarters|purple',name,re.I) else 'smart' if re.search(r'ibo|bob|smart|tv|vu|duplex|parce?ria',name+' '+block,re.I) else None
        if code and platform and counts[platform]<2:result.append({'name':name[:120],'code':code[:100],'platform':platform});counts[platform]+=1
    return result

def access_details(a):
    c=unseal(a['credentials']);details=unseal(a['trial_details'])
    return {'username':a['username'],'password':c.get('password',''),'plan':a['plan'],'expiresAt':iso(a['expires_at']),
            'connections':a['access_count'],'paymentUrl':a['payment_url'],'apps':details.get('apps',[]),'supportWhatsapp':setting('support_whatsapp')}

def make_trial(body):
    device=session.setdefault('device',uid());ip=request.remote_addr or ''
    dh=digest(app.secret_key+':device:'+device);ih=digest(app.secret_key+':ip:'+ip);claim=uid()
    # Limpa registros órfãos ou incertos anteriores sem conta ativa criada
    execute("DELETE FROM trial_claims WHERE state IN ('pending','uncertain') OR account_id IS NULL")
    url=resolve_trial_api_url()
    if not url:
        raise ApiError('Configure a API de testes no admin.',503)
    try:
        execute('INSERT INTO trial_claims(id,device_hash,ip_hash,created_at,state) VALUES(?,?,?,?,?)',(claim,dh,ih,now(),'pending'))
    except sqlite3.IntegrityError:
        raise ApiError('Você já utilizou o teste gratuito. Entre com seu acesso ou fale com o suporte.',409,'TRIAL_ALREADY_USED')
    try:
        raw = ''
        for payload in (b'{}', json.dumps({'message':'teste','text':'teste'}).encode('utf-8')):
            try:
                req=urllib.request.Request(url,data=payload,method='POST',headers={'Content-Type':'application/json','User-Agent':'Mozilla/5.0','Accept':'*/*'})
                with urllib.request.urlopen(req,timeout=25,context=SSL_CTX) as response:
                    raw=_read_http_decoded(response, 2000000)
                if raw and ('username' in raw.lower() or 'usu' in raw.lower() or 'senha' in raw.lower()):
                    break
            except Exception:
                continue
        if not raw:
            raise ApiError('Não foi possível conectar à API de testes.',502)
        try:
            raw_data=json.loads(raw)
            if isinstance(raw_data,dict) and isinstance(raw_data.get('data'),dict):
                raw_data={**raw_data,**raw_data['data']}
        except Exception:
            raw_data={'reply':raw}
        parsed=parse_trial_api_response(json.dumps(raw_data,ensure_ascii=False) if isinstance(raw_data,dict) else raw,{'dns_list':setting('provider_dns'),'trial_duration_hours':'6'})
        if not parsed['username'] or not parsed['password']:
            execute('DELETE FROM trial_claims WHERE id=?',(claim,))
            raise ApiError('O provedor não retornou credenciais válidas.',502)
        data=raw_data if isinstance(raw_data,dict) else {}
        expiry=(
            timestamp(data.get('expiresAt') or data.get('expires_at') or data.get('expiresAtFormatted') or parsed.get('expires_formatted'))
            or (int(parsed.get('expires_at') or (int(time.time())+6*3600))*1000)
        )
        server=(
            server_origin(data.get('dns'))
            or server_origin(parsed.get('m3u_url'))
            or server_origin(parsed.get('dns'))
            or candidate_servers()[0]
        )
        c={'username':parsed['username'],'password':parsed['password'],'server':server,'servers':candidate_servers(server)}
        try:
            provider_json(c, timeout=3)
        except Exception:
            pass
        trial={
            'expiry':expiry,
            'plan':parsed['plan_type'],
            'connections':parsed['max_connections'],
            'paymentUrl':safe_url(parsed['payment_link']),
            'apps':apps_from_reply((data.get('reply') if isinstance(data,dict) else '') or parsed['raw_message'])
        }
        a=save_account(c,trial=trial,body=body)
        execute('UPDATE trial_claims SET account_id=?,state=? WHERE id=?',(a['id'],'created',claim))
        return login_response(a,access_details(a))
    except ApiError:
        execute('DELETE FROM trial_claims WHERE id=? AND state!=?',(claim,'created'))
        raise
    except Exception:
        execute('DELETE FROM trial_claims WHERE id=? AND state!=?',(claim,'created'))
        raise ApiError('Não foi possível confirmar a geração do teste no momento. Tente novamente.',502)

def do_login(body):
    username=str(body.get('username','')).strip()
    password=str(body.get('password','')).strip()
    custom_srv=server_origin(body.get('verifiedServer') or body.get('server') or body.get('dns'))
    if username.startswith(('http://','https://')) and 'username=' in username:
        try:
            sp=urllib.parse.urlsplit(username)
            qs=urllib.parse.parse_qs(sp.query)
            custom_srv=server_origin(f"{sp.scheme}://{sp.netloc}") or custom_srv
            if qs.get('username'):username=qs['username'][0].strip()
            if qs.get('password') and not password:password=qs['password'][0].strip()
        except Exception:
            pass
    if not username or not password or len(username)>100 or len(password)>200:
        raise ApiError('Informe usuário e senha válidos.')
    existing=row('SELECT * FROM accounts WHERE username=? AND revoked=0',(username,))
    servers=candidate_servers(custom_srv or (unseal(existing['credentials']).get('server') if existing else None))
    if not servers:
        raise ApiError('Configure o DNS do provedor no admin.',503)

    # 1. Se o navegador já validou diretamente no servidor IPTV, usa os dados confirmados
    browser_uinfo=body.get('userInfo') if isinstance(body.get('userInfo'),dict) else None
    if browser_uinfo and str(browser_uinfo.get('auth'))=='1':
        c={'username':username,'password':password,'server':custom_srv or servers[0],'servers':servers}
        a=save_account(c,info={'user_info':browser_uinfo},body=body)
        return login_response(a)

    # 2. Tenta validar rapidamente pelo backend nos servidores candidatos
    c_probe={'username':username,'password':password,'server':servers[0],'servers':servers}
    try:
        info=provider_json(c_probe,timeout=4)
        uinfo=(info.get('user_info') if isinstance(info,dict) else None) or {}
        if str(uinfo.get('auth'))=='1' or str(uinfo.get('status','')).lower() in ('active','trial'):
            exp_ts=timestamp(uinfo.get('exp_date'))
            state_str=str(uinfo.get('status') or '').lower()
            if (exp_ts and exp_ts<=now()) or state_str in ('expired','disabled','banned'):
                raise ApiError('Seu acesso expirou. Renove para continuar.',403,'ACCESS_EXPIRED')
            a=save_account(c_probe,info={'user_info':uinfo},body=body)
            return login_response(a)
        elif str(uinfo.get('auth'))=='0':
            raise ApiError('Usuário ou senha inválidos.',401,'LOGIN_REQUIRED')
    except ApiError:
        raise
    except Exception:
        pass

    # 3. Se a conta já existe como teste válido, confere senha e atualiza lista de DNS
    if existing and existing['is_trial']:
        old_creds=unseal(existing['credentials'])
        if not hmac.compare_digest(str(old_creds.get('password','')),password):
            raise ApiError('Usuário ou senha inválidos.',401,'LOGIN_REQUIRED')
        c_upd={'username':username,'password':password,'server':old_creds.get('server') or servers[0],'servers':servers}
        execute('UPDATE accounts SET credentials=? WHERE id=?',(seal(c_upd),existing['id']))
        return login_response(row('SELECT * FROM accounts WHERE id=?',(existing['id'],)))

    # 4. Credenciais do servidor quando o IP da VPS sofre bloqueio: permite conexão pelo navegador
    c={'username':username,'password':password,'server':servers[0],'servers':servers}
    a=save_account(c,body=body)
    execute("UPDATE accounts SET provider_status='Active',plan=COALESCE(plan,'Assinatura IPTV'),last_verified=? WHERE id=?",(now(),a['id']))
    return login_response(row('SELECT * FROM accounts WHERE id=?',(a['id'],)))

def renew_account(a):
    try:
        c=unseal(a['credentials']);info=provider_json(c);u=info.get('user_info') or {}
        if str(u.get('auth'))=='1':
            return save_account(c,info),None
    except (urllib.error.URLError,TimeoutError,ValueError):pass
    return a,'A renovação ainda não foi confirmada pelo provedor.'

def library_sync(a):
    return {'favorites':rows('SELECT content_id AS id,content_type AS type,title,artwork FROM favorites WHERE account_id=? ORDER BY created_at DESC',(a['id'],)),
            'progress':rows('SELECT content_id AS id,content_type AS type,series_id AS seriesId,title,artwork,position_seconds AS position,duration_seconds AS duration,updated_at AS updatedAt FROM watch_progress WHERE account_id=? AND completed=0 AND position_seconds>15 ORDER BY updated_at DESC LIMIT 24',(a['id'],)),
            'serverNow':now(),'userId':a['id']}

def metadata(body):
    kind=str(body.get('type',''));cid=str(body.get('id',''));item=body.get('item') or {}
    if kind not in ('live','movie','series') or not re.fullmatch(r'\d+',cid) or not isinstance(item,dict) or not str(item.get('title','')).strip():
        raise ApiError('Conteúdo inválido.')
    return kind,cid,str(item['title'])[:300],safe_url(item.get('artwork'))

def enrich_location(play_id,ip):
    try:
        if not ipaddress.ip_address(ip).is_global:return
        if ip in GEO_CACHE:geo=GEO_CACHE[ip]
        else:
            url='http://ip-api.com/json/'+urllib.parse.quote(ip,safe='')+'?fields=status,city,regionName,country'
            with urllib.request.urlopen(url,timeout=3) as response:geo=json.loads(response.read(8192))
            if geo.get('status')!='success':return
            if len(GEO_CACHE)>1000:GEO_CACHE.clear()
            GEO_CACHE[ip]=geo
        execute('UPDATE plays SET city=?,region=?,country=? WHERE id=?',(geo.get('city'),geo.get('regionName'),geo.get('country'),play_id))
    except Exception:pass

def play_start(a,body):
    kind,cid,title,artwork=metadata(body);ci=client_info(body);play=uid();t=now();c=unseal(a['credentials']);ext=str((body.get('item') or {}).get('extension') or 'mp4')
    if not re.fullmatch(r'[a-zA-Z0-9]{2,6}',ext):ext='mp4'
    if kind=='live':ext='ts'
    series=str(body.get('seriesId',''))[:50] if kind=='series' else None
    with database() as db:
        db.execute("UPDATE plays SET state='stopped',ended_at=? WHERE session_id=? AND state IN ('playing','paused','loading','buffering')",(t,a['session_id']))
        db.execute('INSERT INTO plays(id,account_id,session_id,content_id,content_type,title,artwork,series_id,episode_label,started_at,last_seen,state,ip,device_model,platform,browser,user_agent) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
          (play,a['id'],a['session_id'],cid,kind,title,artwork,series,str((body.get('item') or {}).get('episodeLabel',''))[:100],t,t,'loading',ci['ip'],ci['model'],ci['platform'],ci['browser'],ci['ua']))
    POOL.submit(enrich_location,play,ci['ip'])
    last=row('SELECT * FROM watch_progress WHERE account_id=? AND content_type=? AND content_id=?',(a['id'],kind,cid))
    segment={'movie':'movie','series':'series','live':'live'}[kind]
    srv=(c.get('server') or candidate_servers()[0]).rstrip('/')
    url=srv+'/'+segment+'/'+urllib.parse.quote(c['username'],safe='')+'/'+urllib.parse.quote(c['password'],safe='')+'/'+cid+'.'+ext
    return jsonify(url=url,direct=True,format=ext,playId=play,item={'id':cid,'type':kind,'title':title,'artwork':artwork},resume=last['position_seconds'] if last and not last['completed'] else 0,account=public_account(a),serverNow=t)

def heartbeat(a,body):
    play=row('SELECT * FROM plays WHERE id=? AND account_id=? AND session_id=?',(str(body.get('playId','')),a['id'],a['session_id']))
    if not play:raise ApiError('Reprodução encerrada.',404)
    state=str(body.get('state','paused'));state=state if state in ('playing','paused','ended','stopped','buffering') else 'paused'
    pos=max(0,min(float(body.get('position') or 0),1e7));duration=max(0,min(float(body.get('duration') or 0),1e7));t=now()
    delta=min(30,max(0,int((t-play['last_seen'])/1000))) if play['state']=='playing' else 0
    with database() as db:
        db.execute('UPDATE plays SET last_seen=?,watched_seconds=watched_seconds+?,position_seconds=?,duration_seconds=?,state=?,ended_at=? WHERE id=?',(t,delta,pos,duration,state,t if state in ('stopped','ended') else None,play['id']))
        if play['content_type']!='live':
            completed=state=='ended' or duration>0 and pos>=duration-30
            db.execute('INSERT INTO watch_progress(account_id,content_type,content_id,series_id,title,artwork,position_seconds,duration_seconds,completed,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(account_id,content_type,content_id) DO UPDATE SET position_seconds=excluded.position_seconds,duration_seconds=excluded.duration_seconds,completed=excluded.completed,updated_at=excluded.updated_at',
              (a['id'],play['content_type'],play['content_id'],play['series_id'],play['title'],play['artwork'],pos,duration,int(completed),t))
    return jsonify(account=public_account(a),serverNow=t)

def admin_ok():
    token=session.get('admin_token')
    return bool(token and row('SELECT id FROM admin_sessions WHERE id=? AND expires_at>? AND credential_version=?',(digest(token),now(),int(setting('admin_version','1')))))
def rate_identifier(kind):return digest(kind+':'+(request.remote_addr or ''))
def rate_guard(kind):
    r=row('SELECT * FROM admin_auth_attempts WHERE identifier=?',(rate_identifier(kind),))
    if r and r['blocked_until']>now():raise ApiError('Muitas tentativas. Aguarde 15 minutos.',429)
def rate_bad(kind):
    key=rate_identifier(kind);r=row('SELECT * FROM admin_auth_attempts WHERE identifier=?',(key,));t=now()
    attempts=r['attempts']+1 if r and r['period_start']>t-900000 else 1
    execute('INSERT INTO admin_auth_attempts(identifier,attempts,period_start,blocked_until) VALUES(?,?,?,?) ON CONFLICT(identifier) DO UPDATE SET attempts=excluded.attempts,period_start=excluded.period_start,blocked_until=excluded.blocked_until',(key,attempts,r['period_start'] if r and attempts>1 else t,t+900000 if attempts>=8 else 0))
def rate_clear(kind):execute('DELETE FROM admin_auth_attempts WHERE identifier=?',(rate_identifier(kind),))

def admin_route(path,body):
    if path=='admin/session':return jsonify(authenticated=admin_ok())
    if path=='admin/login' and request.method=='POST':
        rate_guard('admin')
        if not hmac.compare_digest(str(body.get('username','')),setting('admin_user')) or not check_password_hash(setting('admin_hash'),str(body.get('password',''))):
            rate_bad('admin');raise ApiError('Usuário ou senha do admin inválidos.',401)
        rate_clear('admin');token=secrets.token_urlsafe(32)
        execute('INSERT INTO admin_sessions(id,expires_at,credential_version) VALUES(?,?,?)',(digest(token),now()+8*3600000,int(setting('admin_version','1'))))
        session['admin_token']=token;return jsonify(authenticated=True)
    if not admin_ok():raise ApiError('Área exclusiva do administrador.',403,'ADMIN_REQUIRED')
    if path=='admin/logout' and request.method=='POST':
        execute('DELETE FROM admin_sessions WHERE id=?',(digest(session.pop('admin_token','')),));return jsonify(authenticated=False)
    if path=='admin/settings':
        if request.method=='PATCH':
            support=re.sub(r'\D','',str(body.get('supportWhatsapp','')))
            if not re.fullmatch(r'[1-9]\d{7,14}',support):raise ApiError('Informe o WhatsApp com país e DDD.')
            dns=server_origin(body.get('dns'));api=str(body.get('trialApiUrl','')).strip()
            if not dns:raise ApiError('Informe um DNS HTTP ou HTTPS público válido.')
            if api and not safe_url(api):raise ApiError('Informe uma API de testes válida.')
            username=str(body.get('username') or setting('admin_user')).strip();password=str(body.get('newPassword') or '')
            if not re.fullmatch(r'[a-zA-Z0-9_.@-]{3,64}',username):raise ApiError('Usuário administrativo inválido.')
            if password and not 12<=len(password)<=200:raise ApiError('A nova senha deve ter de 12 a 200 caracteres.')
            change=username!=setting('admin_user') or bool(password)
            if change and not check_password_hash(setting('admin_hash'),str(body.get('currentPassword',''))):raise ApiError('Senha atual incorreta.')
            updates={'provider_dns':dns,'support_whatsapp':support}
            if api:updates['trial_api_url']=seal({'url':api})
            if change:
                updates.update(admin_user=username,admin_hash=generate_password_hash(password or str(body['currentPassword'])),admin_version=str(int(setting('admin_version','1'))+1))
            with database() as db:
                for key,value in updates.items():db.execute('INSERT INTO site_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(key,value))
                if change:
                    db.execute('DELETE FROM admin_sessions')
                    token=secrets.token_urlsafe(32);session['admin_token']=token
                    db.execute('INSERT INTO admin_sessions(id,expires_at,credential_version) VALUES(?,?,?)',(digest(token),now()+8*3600000,int(updates['admin_version'])))
            return jsonify(saved=True)
        return jsonify(username=setting('admin_user'),dns=(setting('provider_dns').splitlines()[0] if setting('provider_dns') else ''),trialApiConfigured=bool(resolve_trial_api_url()),supportWhatsapp=setting('support_whatsapp'))
    online_where="p.last_seen>? AND p.state='playing' AND s.expires_at>? AND a.revoked=0 AND (a.expires_at IS NULL OR a.expires_at>?) AND (a.is_trial=0 OR a.trial_deadline>?)"
    if path=='admin/overview':
        users=row('SELECT COUNT(*) AS users,SUM(is_trial) AS trials FROM accounts');claims=row('SELECT COUNT(*) AS count FROM trial_claims')
        online=row('SELECT COUNT(*) AS count FROM plays p JOIN sessions s ON s.id=p.session_id JOIN accounts a ON a.id=p.account_id WHERE '+online_where,(now()-45000,now(),now(),now()))
        return jsonify(users=users['users'],trials=users['trials'] or 0,claims=claims['count'],online=online['count'])
    if path=='admin/online':return jsonify(items=rows('SELECT p.*,a.username,a.is_trial FROM plays p JOIN sessions s ON s.id=p.session_id JOIN accounts a ON a.id=p.account_id WHERE '+online_where+' ORDER BY p.last_seen DESC LIMIT 250',(now()-45000,now(),now(),now())))
    page=max(1,request.args.get('page',1,type=int));offset=(page-1)*50
    if path=='admin/users':
        q='%'+request.args.get('q','')[:80]+'%'
        return jsonify(items=rows('SELECT id,username,plan,created_at,expires_at,is_trial,provider_status,last_ip,device_model,platform,browser FROM accounts WHERE username LIKE ? ORDER BY created_at DESC LIMIT 50 OFFSET ?',(q,offset)),total=row('SELECT COUNT(*) AS n FROM accounts WHERE username LIKE ?',(q,))['n'],page=page)
    match=re.fullmatch(r'admin/users/([a-zA-Z0-9_-]+)(/history)?',path)
    if match:
        account=row('SELECT id,username,created_at FROM accounts WHERE id=?',(match[1],))
        if not account:raise ApiError('Usuário não encontrado.',404)
        if match[2]:return jsonify(user=account,items=rows('SELECT * FROM plays WHERE account_id=? ORDER BY started_at DESC LIMIT 50 OFFSET ?',(account['id'],offset)),total=row('SELECT COUNT(*) AS n FROM plays WHERE account_id=?',(account['id'],))['n'],page=page)
        if request.method=='DELETE':
            execute('DELETE FROM accounts WHERE id=?',(account['id'],));return jsonify(removed=True,trialReleased=True)
    raise ApiError('Rota administrativa não encontrada.',404)

@app.before_request
def protect_writes():
    if request.path.startswith('/api/') and request.method not in ('GET','HEAD','OPTIONS'):
        if request.headers.get('Sec-Fetch-Site')=='cross-site':
            raise ApiError('Solicitação não autorizada.',403)
        origin=request.headers.get('Origin')
        if origin:
            try:
                if urllib.parse.urlsplit(origin).hostname != urllib.parse.urlsplit(request.host_url).hostname:
                    raise ApiError('Solicitação não autorizada.',403)
            except ApiError:
                raise
            except Exception:
                pass
        if not request.is_json:raise ApiError('Envie dados JSON.',415)

@app.after_request
def response_headers(response):
    response.headers['Cache-Control']='no-store' if request.path.startswith('/api/') else 'no-cache'
    response.headers['X-Content-Type-Options']='nosniff';response.headers['Referrer-Policy']='no-referrer'
    return response

@app.route('/api/<path:path>',methods=['GET','POST','PATCH','DELETE'])
def api(path):
    body=request.get_json(silent=True) or {} if request.method!='GET' else {}
    if not isinstance(body,dict):raise ApiError('Solicitação inválida.')
    if path.startswith('admin/'):return admin_route(path,body)
    if path=='config':return jsonify(supportWhatsapp=setting('support_whatsapp'),connectionMode='browser',servers=candidate_servers())
    if path=='session':
        session.setdefault('device',uid());session.permanent=True
        a=current_account(False);error=None
        if a and request.args.get('refresh')=='1':a,error=renew_account(a)
        return jsonify(authenticated=bool(a),account=public_account(a),serverNow=now(),verificationError=error)
    if path=='login' and request.method=='POST':
        rate_guard('login')
        try:result=do_login(body)
        except ApiError:
            rate_bad('login');raise
        rate_clear('login');return result
    if path=='trial' and request.method=='POST':return make_trial(body)
    if path=='logout' and request.method=='POST':
        execute('DELETE FROM sessions WHERE id=?',(digest(session.pop('user_token','')),));return jsonify(signedOut=True)
    if path=='access':return jsonify(access_details(current_account()))
    a=current_account(active=True)
    if path=='browser-access':
        c=unseal(a['credentials'])
        servers=candidate_servers(c.get('server'))
        primary_srv=servers[0]
        return jsonify(username=c['username'],password=c['password'],server=primary_srv,servers=servers,playlistUrl=playlist_url({**c,'server':primary_srv}),account=public_account(a),serverNow=now())
    if path=='xtream':
        c=unseal(a['credentials'])
        action=request.args.get('action') or None
        params={k:v for k,v in request.args.items() if k!='action'}
        try:
            data=provider_json(c,action=action,params=params,timeout=10)
            if c.get('server'):
                execute('UPDATE accounts SET credentials=? WHERE id=?',(seal(c),a['id']))
            return jsonify(data=data,server=c.get('server'))
        except Exception:
            raise ApiError('Não foi possível consultar a API do provedor.',502)
    if path=='m3u':
        c=unseal(a['credentials'])
        text, srv = fetch_m3u_text(c, timeout=18)
        if not text:
            raise ApiError('Não foi possível consultar a playlist M3U do provedor.',502)
        if srv and srv != c.get('server'):
            c['server'] = srv
            execute('UPDATE accounts SET credentials=? WHERE id=?',(seal(c),a['id']))
        return jsonify(text=text,server=srv)
    if path=='sync':return jsonify(library_sync(a))
    if path=='favorites':
        if request.method=='GET':return jsonify(items=library_sync(a)['favorites'])
        if request.method=='DELETE':
            execute('DELETE FROM favorites WHERE account_id=? AND content_type=? AND content_id=?',(a['id'],str(body.get('type')),str(body.get('id'))));return jsonify(saved=False)
        if request.method=='POST':
            kind,cid,title,artwork=metadata(body)
            execute('INSERT INTO favorites(account_id,content_id,content_type,title,artwork,created_at) VALUES(?,?,?,?,?,?) ON CONFLICT(account_id,content_type,content_id) DO NOTHING',(a['id'],cid,kind,title,artwork,now()));return jsonify(saved=True)
    if path=='play' and request.method=='POST':return play_start(a,body)
    if path=='heartbeat' and request.method=='POST':return heartbeat(a,body)
    raise ApiError('Rota não encontrada.',404)

@app.errorhandler(Exception)
def unexpected_error(error):
    from werkzeug.exceptions import HTTPException
    if isinstance(error,HTTPException):return jsonify(error=error.description),error.code
    log.error('Erro interno: %s',type(error).__name__)
    return jsonify(error='Não foi possível concluir a solicitação.',code='SERVER_ERROR'),500

@app.route('/',defaults={'path':''})
@app.route('/<path:path>')
def assets(path):
    if path in ('','login','home','admin','admin/history'):path='index.html'
    asset=ASSETS.get('/'+path)
    if not asset:return Response('Página não encontrada',status=404)
    return Response(asset['body'],content_type=asset['type'])

